  const description=`Level ${level}, day ${scale.day??'loading'}; prize pool ${amount} ETH${days?`; ${scale.day??'unknown'} of 30 days toward target`:scale.ready?'; target met, expanded pool scale':''}${!jackpot&&thresholdTitle?`; ${thresholdTitle}`:''}`;
  thermo.title=description;thermo.setAttribute('aria-label',description);track.setAttribute('aria-valuetext',description);
